def get_cluster_state(scope, time):
    node_machines = node_by_title(doc, f"{scope}: Machines")
    machines = {row['machine']: {'cpu': int(row['CPU']), 'mem': int(row['memory']), 'up': True} for idx, row in table_rows(node_machines)}

    # Handle failures/returns
    for idx, row in table_rows(node_machines):
        m = row['machine']
        fail_at = row['fails at']
        ret_at = row['returns at']
        if fail_at != '-' and int(fail_at) <= time:
            if ret_at == '-' or int(ret_at) > time:
                machines[m]['up'] = False

    # Tasks running at time
    node_tasks = node_by_title(doc, f"{scope}: Task log")
    rows = table_rows(node_tasks)
    running_tasks = {} # machine -> [tasks]

    for idx, row in rows:
        t = int(row['time'])
        if t > time:
            break
        task = row['task']
        event = row['event']
        machine = row['machine']

        if event == 'start':
            running_tasks.setdefault(machine, []).append(row)
        elif event == 'finish' or event == 'fail' or event == 'evict':
            if machine in running_tasks:
                running_tasks[machine] = [r for r in running_tasks[machine] if r['task'] != task]

    return machines, running_tasks

