def find_waiting_tasks(time_limit):
    node = node_by_title(doc, 'Cell window 12: Task log')
    rows = table_rows(node)
    tasks = {}
    for row_idx, row in rows:
        tid = row['task']
        if tid not in tasks:
            tasks[tid] = {'submit': None, 'start': None, 'priority': int(row['priority'])}
        if row['event'] == 'submit':
            tasks[tid]['submit'] = int(row['time'])
        elif row['event'] == 'start':
            tasks[tid]['start'] = int(row['time'])

    waiting = []
    for tid, info in tasks.items():
        if info['submit'] is not None and (info['start'] is None or info['start'] > time_limit):
            if info['submit'] <= time_limit:
                waiting.append((tid, info['priority'], info['submit']))

    # Sort by priority (desc), then submit time (asc), then tid (asc)
    waiting.sort(key=lambda x: (-x[1], x[2], x[0]))
    return waiting

