def get_cluster_state(doc, window, time):
    nodes = scope_nodes(doc, window)
    machines_node = next(n for n in nodes if "Machines" in n['title'])
    task_log_node = next(n for n in nodes if "Task log" in n['title'])

    machines_table = machines_node['table']
    task_log_table = task_log_node['table']

    # Task properties
    tasks = {}
    for row in task_log_table['rows'][1:]:
        t_id = row[1]
        if row[7] == 'submit':
            tasks[t_id] = {
                'cpu': int(row[4]),
                'mem': int(row[5]),
                'priority': int(row[3]),
                'runtime': int(row[6])
            }

    # Machine state
    machines = {}
    for row in machines_table['rows'][1:]:
        m_id = row[0]
        machines[m_id] = {
            'cpu': int(row[1]),
            'mem': int(row[2]),
            'fail': int(row[3]) if row[3] != '-' else None,
            'return': int(row[4]) if row[4] != '-' else None,
            'used_cpu': 0,
            'used_mem': 0,
            'running_tasks': set(),
            'up': True
        }

    for row in task_log_table['rows'][1:]:
        t_time = int(row[0])
        if t_time > time:
            break

        t_id = row[1]
        event = row[7]
        m_id = row[8]

        # Handle machine failures
        for mid, mstate in machines.items():
            if mstate['fail'] == t_time:
                mstate['up'] = False
                # All tasks on this machine fail
                for tid in list(mstate['running_tasks']):
                    t_req = tasks[tid]
                    mstate['used_cpu'] -= t_req['cpu']
                    mstate['used_mem'] -= t_req['mem']
                mstate['running_tasks'].clear()

        if event == 'start':
            t_req = tasks[t_id]
            machines[m_id]['used_cpu'] += t_req['cpu']
            machines[m_id]['used_mem'] += t_req['mem']
            machines[m_id]['running_tasks'].add(t_id)
        elif event == 'finish' or event == 'evict' or event == 'fail':
            if m_id != '-':
                t_req = tasks[t_id]
                machines[m_id]['used_cpu'] -= t_req['cpu']
                machines[m_id]['used_mem'] -= t_req['mem']
                machines[m_id]['running_tasks'].discard(t_id)

    # Handle machines that failed but then returned before 'time'
    for mid, mstate in machines.items():
        if mstate['fail'] is not None and mstate['return'] is not None and mstate['return'] <= time:
            mstate['up'] = True

    return machines, tasks

