def get_free_cap(time):
    running = {m: set() for m in ['M01', 'M02', 'M03', 'M04', 'M05', 'M06', 'M07', 'M08']}
    sorted_rows = sorted(rows_log, key=lambda x: int(x[1]['time']))
    for _, row in sorted_rows:
        t = int(row['time'])
        if t > time: break
        task, event, machine = row['task'], row['event'], row['machine']
        if event == 'start':
            if machine: running[machine].add(task)
        elif event in ['finish', 'evict', 'fail']:
            if machine and task in running[machine]:
                running[machine].remove(task)

    # Calculate free capacity
    free_cap = {}
    task_reqs = {}
    for _, row in rows_log:
        if row['task'] not in task_reqs:
            task_reqs[row['task']] = (int(row['CPU']), int(row['memory']))

    mach_caps = {}
    for _, row in rows_mach:
        mach_caps[row['machine']] = (int(row['CPU']), int(row['memory']))

    for m, tasks in running.items():
        cpu_used = sum(task_reqs[t][0] for t in tasks)
        mem_used = sum(task_reqs[t][1] for t in tasks)
        free_cap[m] = (mach_caps[m][0] - cpu_used, mach_caps[m][1] - mem_used)
    return free_cap

