def get_state_at_time(window, time):
    caps = get_machine_capacities(window)
    requests = get_task_requests(window)
    current_tasks = {} # task -> machine

    log_node = node_by_title(doc, f"{window}: Task log")
    rows_list = [row for idx, row in table_rows(log_node)]

    def event_priority(event):
        if event == 'finish': return 0
        if event == 'fail': return 1
        if event == 'submit': return 2
        if event in ['start', 'evict']: return 3
        return 4

    sorted_rows = sorted(rows_list, key=lambda x: (int(x['time']), event_priority(x['event'])))

    for row in sorted_rows:
        t = int(row['time'])
        event = row['event']
        task = row['task']
        machine = row['machine']

        if t > time:
            break
        if t == time and event_priority(event) >= 3:
            break

        if event == 'start':
            current_tasks[task] = machine
        elif event in ['finish', 'fail', 'evict']:
            if task in current_tasks:
                del current_tasks[task]

    free_caps = {m: dict(caps[m]) for m in caps}
    for task, machine in current_tasks.items():
        req = requests[task]
        free_caps[machine]['CPU'] -= req['CPU']
        free_caps[machine]['memory'] -= req['memory']

    return free_caps, current_tasks

