def get_running_at_time(time, chapter):
    task_node = node_by_title(doc, f"{chapter}: Task log")
    rows = table_rows(task_node)
    running = []
    task_status = {} # tid: (start_time, run_time, machine)

    for row_idx, row in rows:
        t = int(row['time'])
        if t > time:
            break
        tid = row['task']
        event = row['event']
        if event == 'start':
            task_status[tid] = (t, int(row['run time']), row['machine'])
        elif event == 'finish':
            if tid in task_status:
                del task_status[tid]
        elif event == 'fail' or event == 'evict':
            if tid in task_status:
                del task_status[tid]

    for tid, (start, duration, machine) in task_status.items():
        if start + duration > time:
            running.append((tid, machine))

    return running

