# Running tasks at t=602
running_at_602 = {}
for row in full_log:
    time = int(row['time'])
    if time > 602: break
    tid, event, machine = row['task'], row['event'], row['machine']
    if event == 'start':
        finish_time = time + tasks[tid]['run_time']
        if machine not in running_at_602: running_at_602[machine] = []
        running_at_602[machine].append((tid, finish_time))
    elif event == 'finish':
        if machine in running_at_602:
            running_at_602[machine] = [item for item in running_at_602[machine] if item[0] != tid]
    elif event == 'evict' or event == 'fail':
        if machine in running_at_602:
            running_at_602[machine] = [item for item in running_at_602[machine] if item[0] != tid]

