    free_tier = []
    for tid, finish_time in running_at_602.get(mid, []):
        used_cpu += tasks[tid]['cpu']
        used_mem += tasks[tid]['mem']
        if tasks[tid]['priority'] <= 1:
            free_tier.append(tid)

    if machines[mid]['cpu'] - used_cpu >= t116_cpu and machines[mid]['mem'] - used_mem >= t116_mem:
        print(f"T116 fits on {mid} by first fit")
        break

    # Preemption
    # We need the start times of free_tier tasks to sort them (lowest priority, most recent start, higher tid)
    # Let's find start times
    free_tier_details = []
    for tid in free_tier:
        start_t = 0
        for row in full_log:
