                start_t = int(row['time'])
                break
        free_tier_details.append({'tid': tid, 'priority': tasks[tid]['priority'], 'start': start_t})

    free_tier_details.sort(key=lambda x: (x['priority'], -x['start'], -int(x['tid'][1:])))

    temp_cpu, temp_mem = machines[mid]['cpu'] - used_cpu, machines[mid]['mem'] - used_mem
    evicted = []
