        tid = item['tid']
        temp_cpu += tasks[tid]['cpu']
        temp_mem += tasks[tid]['mem']
        evicted.append(tid)

    if temp_cpu >= t116_cpu and temp_mem >= t116_mem:
        print(f"T116 fits on {mid} by preemption, evicting {evicted}")
        break

