def analyze_t093_wait(window):
    log_node = node_by_title(doc, f"{window}: Task log")
    rows = table_rows(log_node)

    tasks = {}
    for idx, row in rows:
        tid = row['task']
        if tid not in tasks:
            tasks[tid] = {
                'priority': int(row['priority']),
                'cpu': int(row['CPU']),
                'mem': int(row['memory']),
                'run_time': int(row['run time']),
                'submit': None,
                'start': None,
                'finish': None,
                'evict': None,
                'fail': None,
                'machine': None
            }
        if row['event'] == 'submit':
            tasks[tid]['submit'] = int(row['time'])
        elif row['event'] == 'start':
            tasks[tid]['start'] = int(row['time'])
            tasks[tid]['machine'] = row['machine']
        elif row['event'] == 'finish':
            tasks[tid]['finish'] = int(row['time'])
        elif row['event'] == 'evict':
            tasks[tid]['evict'] = int(row['time'])
        elif row['event'] == 'fail':
            tasks[tid]['fail'] = int(row['time'])

    # T093 submit 705, start 1025.
    t093_submit = 705
    t093_start = 1025

    # Let's find all tasks that could have been in the queue and had higher priority than T093 (priority 0)
    # between 705 and 1025.
    higher_priority_tasks = []
    for tid, info in tasks.items():
        if tid == 'T093': continue
        if info['priority'] > 0:
            # Task must be submitted by the time we are considering.
            # And it must not have finished before T093 submitted.
            if info['submit'] is not None and (info['submit'] < t093_start):
                higher_priority_tasks.append(tid)

    return higher_priority_tasks

