def get_usage_at_time(window, time):
    log_node = node_by_title(doc, f"{window}: Task log")
    rows = table_rows(log_node)

    active_tasks = {} # tid -> (machine, cpu, mem)
    for idx, row in rows:
        t = int(row['time'])
        if t > time: break
        tid = row['task']
        event = row['event']
        if event == 'start':
            # Find the task's cpu and mem from its submit row
            cpu, mem = 0, 0
            for idx2, row2 in rows:
                if row2['task'] == tid and row2['event'] == 'submit':
                    cpu, mem = int(row2['CPU']), int(row2['memory'])
                    break
            active_tasks[tid] = (row['machine'], cpu, mem)
        elif event in ['finish', 'evict', 'fail']:
            if tid in active_tasks:
                del active_tasks[tid]

    usage = {m: {'cpu': 0, 'mem': 0} for m in ['M01', 'M02', 'M03', 'M04', 'M05', 'M06', 'M07', 'M08']}
    for tid, (mid, cpu, mem) in active_tasks.items():
        usage[mid]['cpu'] += cpu
        usage[mid]['mem'] += mem
    return usage, active_tasks

