def find_tasks(doc, window, task_ids):
    # Find the task log section for the window
    log_node = None
    for node in doc['nodes']:
        if node['title'] == f"{window}: Task log":
            log_node = node
            break

    if not log_node:
        return "Task log not found"

    rows = log_node['table']['rows']
    cols = log_node['table']['columns']

    task_data = {}
    for row in rows:
        row_dict = dict(zip(cols, row))
        tid = row_dict['task']
        if tid in task_ids:
            if tid not in task_data:
                task_data[tid] = []
            task_data[tid].append(row_dict)

    return task_data

